#!/usr/bin/env node
/**
 * 构建 taibu-divination skill 的自包含产物（维护工具，最终用户/agent 不需要运行）：
 *   1. 用 esbuild 把 packages/core/dist/mcp 打成单文件 ESM bundle（零安装的来源）
 *   2. 从 bundle 的 listToolDefinitions() 生成 references/<tool>.md
 *   3. 把工具选择表注入 SKILL.md 的 TOOLS 标记之间（最后一列链接该体系的默认方法）
 *
 * 方法与 SKILL.md 的方法目录由 scripts/build-methods.mjs 生成。
 * 用法：pnpm -C packages/core build && node scripts/build-skill-bundle.mjs
 * 升级 core 版本后重跑本脚本并提交 bundle + references 的变更。
 */
import { build } from 'esbuild';
import { readFileSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { SKILL_DIR } from './build-methods.mjs';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const coreVersion = require(path.join(repoRoot, 'packages/core/package.json')).version;

const entry = path.join(repoRoot, 'packages/core/dist/mcp/index.js');
const skillDir = SKILL_DIR;
const bundlePath = path.join(skillDir, 'scripts/vendor/taibu-core.bundle.mjs');
const referencesDir = path.join(skillDir, 'references');
const skillMdPath = path.join(skillDir, 'SKILL.md');

// astrology/calculate.js 用 createRequire 做运行时 require，esbuild 无法静态打包，
// 这里改写为等价的静态 import（CJS 默认导出互操作后解构结果一致）。
const fixAstrologyRequire = {
  name: 'fix-astrology-runtime-require',
  setup(buildApi) {
    buildApi.onLoad({ filter: /domains[\\/]astrology[\\/]calculate\.js$/ }, (args) => {
      const source = readFileSync(args.path, 'utf8');
      // createRequire 依赖真实模块解析，必须改写为静态 import。三条语句可能被
      // 其它静态 import 分隔，因此按行定位而不是要求连续前缀。
      const statements = [
        "import { createRequire } from 'node:module';",
        'const require = createRequire(import.meta.url);',
        "const horoscopePackage = require('circular-natal-horoscope-js');",
      ];
      let rewritten = source;
      for (const statement of statements) {
        const lines = rewritten.split('\n');
        const index = lines.indexOf(statement);
        if (index === -1) {
          throw new Error('astrology/calculate.js 的 createRequire 语句发生变化，请更新 build-skill-bundle.mjs 的改写逻辑');
        }
        lines.splice(index, 1);
        rewritten = lines.join('\n');
      }
      return { contents: "import horoscopePackage from 'circular-natal-horoscope-js';\n" + rewritten, loader: 'js' };
    });
  },
};

async function buildBundle() {
  mkdirSync(path.dirname(bundlePath), { recursive: true });
  const result = await build({
    entryPoints: [entry],
    bundle: true,
    format: 'esm',
    platform: 'node',
    target: 'node18',
    minify: true,
    outfile: bundlePath,
    banner: {
      js: `/* taibu-core@${coreVersion} self-contained bundle — generated by scripts/build-skill-bundle.mjs, do not edit. */`,
    },
    plugins: [fixAstrologyRequire],
    logLevel: 'warning',
  });
  if (result.warnings.length > 0) {
    console.warn(`esbuild warnings: ${result.warnings.length}`);
  }
  const sizeMb = (statSync(bundlePath).size / 1024 / 1024).toFixed(2);
  console.log(`bundle: ${path.relative(repoRoot, bundlePath)} (${sizeMb} MB)`);
}

function isRequired(schema, name) {
  return Array.isArray(schema.required) && schema.required.includes(name);
}

function typeLabel(prop) {
  if (prop.enum) return `enum`;
  if (prop.type === 'array') {
    const itemType = prop.items?.type ?? 'any';
    return `${itemType}[]`;
  }
  return prop.type ?? 'any';
}

function describeProp(prop) {
  const parts = [];
  if (prop.description) parts.push(prop.description.replace(/\n+/g, ' '));
  if (prop.enum) parts.push(`可选值: ${prop.enum.map((v) => `\`${v}\``).join(' / ')}`);
  return parts.join('；') || '—';
}

function paramRows(schema, prefix = '') {
  const rows = [];
  for (const [name, prop] of Object.entries(schema.properties ?? {})) {
    const fullName = prefix ? `${prefix}.${name}` : name;
    rows.push(
      `| \`${fullName}\` | ${typeLabel(prop)} | ${isRequired(schema, name) ? '是' : '否'} | ${prop.default !== undefined ? `\`${JSON.stringify(prop.default)}\`` : '—'} | ${describeProp(prop)} |`,
    );
    // 展开一层嵌套（object 属性或 object 数组项），占术参数最多嵌套一层
    const nested = prop.type === 'object' ? prop : prop.type === 'array' && prop.items?.type === 'object' ? prop.items : null;
    if (nested?.properties) {
      const nestedPrefix = prop.type === 'array' ? `${fullName}[]` : fullName;
      rows.push(...paramRows(nested, nestedPrefix));
    }
  }
  return rows;
}

function renderReference(tool) {
  const lines = [];
  lines.push(`# ${tool.title}（\`${tool.name}\`）`);
  lines.push('');
  lines.push(tool.description);
  lines.push('');
  lines.push('## 参数');
  lines.push('');
  lines.push('| 参数 | 类型 | 必填 | 默认 | 说明 |');
  lines.push('| --- | --- | --- | --- | --- |');
  lines.push(...paramRows(tool.inputSchema));
  lines.push('');
  const examples = tool.inputSchema.examples ?? [];
  if (examples.length > 0) {
    lines.push('## 调用示例');
    lines.push('');
    for (const example of examples) {
      lines.push('```bash');
      lines.push(`echo '${JSON.stringify(example)}' | node "$TB/scripts/taibu.mjs" call ${tool.name} -`);
      lines.push('```');
      lines.push('');
    }
  }
  const outputKeys = Object.keys(tool.outputSchema?.properties ?? {});
  if (outputKeys.length > 0) {
    lines.push('## 输出结构（structuredContent 顶层键）');
    lines.push('');
    for (const key of outputKeys) {
      const prop = tool.outputSchema.properties[key];
      const desc = typeof prop === 'object' && prop !== null && 'description' in prop && prop.description ? String(prop.description) : '';
      lines.push(`- \`${key}\`${desc ? `：${desc}` : ''}`);
    }
    lines.push('');
  }
  return lines.join('\n');
}

/** 「八字命盘 - 根据出生信息排四柱命盘，…。」 → the purpose after the title, up to the first full stop. */
function shortDescription(description) {
  const [, afterDash] = description.split(/\s+-\s+/, 2);
  const text = (afterDash ?? description).replace(/\n+/g, ' ');
  return text.split(/[。；]/, 1)[0] || text;
}

async function generateDocs() {
  const bundleUrl = `${pathToFileURL(bundlePath).href}?v=${Date.now()}`;
  const { getToolSystem, listToolDefinitions } = await import(bundleUrl);
  const tools = listToolDefinitions();
  const methodLink = (toolName) => {
    const system = getToolSystem(toolName);
    if (!system) throw new Error(`工具 ${toolName} 未登记所属体系，请更新 scripts/build-methods.mjs 的 SYSTEM_TOOLS`);
    return `[methods/${system}.md](methods/${system}.md)`;
  };

  mkdirSync(referencesDir, { recursive: true });
  for (const tool of tools) {
    writeFileSync(path.join(referencesDir, `${tool.name}.md`), `${renderReference(tool)}\n`.replace(/\n{3,}/g, '\n\n'));
  }
  console.log(`references: ${tools.length} files -> ${path.relative(repoRoot, referencesDir)}`);

  const tableLines = [
    '| 工具名 | 名称 | 用途 | 参数文档 | 方法 |',
    '| --- | --- | --- | --- | --- |',
    ...tools.map(
      (tool) =>
        `| \`${tool.name}\` | ${tool.title} | ${shortDescription(tool.description)} | [references/${tool.name}.md](references/${tool.name}.md) | ${methodLink(tool.name)} |`,
    ),
  ];
  const skillMd = readFileSync(skillMdPath, 'utf8');
  const injected = skillMd.replace(
    /<!-- TOOLS:BEGIN -->[\s\S]*?<!-- TOOLS:END -->/,
    `<!-- TOOLS:BEGIN -->\n${tableLines.join('\n')}\n<!-- TOOLS:END -->`,
  );
  if (injected === skillMd && !skillMd.includes('<!-- TOOLS:BEGIN -->')) {
    throw new Error('SKILL.md 缺少 <!-- TOOLS:BEGIN --> / <!-- TOOLS:END --> 标记');
  }
  writeFileSync(skillMdPath, injected);
  console.log(`SKILL.md tool table updated (${tools.length} tools, taibu-core@${coreVersion})`);
}

await buildBundle();
await generateDocs();
